says otherwise, as __sev_do_cmd_locked() is expected to return -EIO on any
firwmware error.

Reported-by: Alexander Potapenko <glider@google.com>
Reported-by: Sebastian Alba Vives <sebasjosue84@gmail.com>
Fixes: d6112ea0cb34 ("crypto: ccp - introduce SEV_GET_ID2 command")
Cc: stable@vger.kernel.org
Signed-off-by: Sean Christopherson <seanjc@google.com>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
The function sev_ioctl_do_get_id2 in sev-dev.c does not check the return value (ret) or firmware error code (argp->error) after invoking __sev_do_cmd_locked(). If the PSP command fails, e.g., due to an insufficient userspace buffer, the firmware may set data.len to a value larger than the allocated kernel buffer. The subsequent copy_to_user() then reads beyond the buffer, causing a slab-out-of-bounds KASAN error and potential data leak.

Here is the patch:

 static int sev_ioctl_do_get_id2(struct sev_issue_cmd *argp)
 {
 	struct sev_user_data_get_id2 input;
 	struct sev_data_get_id data;
 	void __user *input_address;
 	void *id_blob = NULL;
 	int ret;

 	/* SEV GET_ID is available from SEV API v0.16 and up */
 	if (!sev_version_greater_or_equal(0, 16))
 		return -ENOTSUPP;

 	if (copy_from_user(&input, (void __user *)argp->data, sizeof(input)))
 		return -EFAULT;

 	input_address = (void __user *)input.address;

 	if (input.address && input.length) {
 		/*
 		 * The length of the ID shouldn't be assumed by software since
 		 * it may change in the future.  The allocation size is limited
 		 * to 1 << (PAGE_SHIFT + MAX_PAGE_ORDER) by the page allocator.
 		 * If the allocation fails, simply return ENOMEM rather than
 		 * warning in the kernel log.
 		 */
 		id_blob = kzalloc(input.length, GFP_KERNEL | __GFP_NOWARN);
 		if (!id_blob)
 			return -ENOMEM;

 		data.address = __psp_pa(id_blob);
 		data.len = input.length;
 	} else {
 		data.address = 0;
 		data.len = 0;
 	}

 	ret = __sev_do_cmd_locked(SEV_CMD_GET_ID, &data, &argp->error);

 	/*
 	 * Firmware will return the length of the ID value (either the minimum
 	 * required length or the actual length written), return it to the user.
 	 */
 	input.length = data.len;

 	if (copy_to_user((void __user *)argp->data, &input, sizeof(input))) {
 		ret = -EFAULT;
 		goto e_free;
 	}

+	if (ret || WARN_ON_ONCE(argp->error))
+		goto e_free;
+
 	if (id_blob) {
 		if (copy_to_user(input_address, id_blob, data.len)) {
 			ret = -EFAULT;
 			goto e_free;
 		}
 	}

 e_free:
 	kfree(id_blob);

 	return ret;
 }



